const now = Date.now();
const DAY = 24 * 60 * 60 * 1000;
const results = [];
for (const item of $input.all()) {
  const ad = item.json;
  const snap = ad.snapshot || {};
  const pick = (o) => o && (o.videoHdUrl || o.videoSdUrl || o.video_hd_url || o.video_sd_url);
  let videoUrl = '';
  let card = null;
  for (const v of (snap.videos || [])) { const u = pick(v); if (u) { videoUrl = u; break; } }
  if (!videoUrl) {
    for (const c of (snap.cards || [])) { const u = pick(c); if (u) { videoUrl = u; card = c; break; } }
  }
  if (!videoUrl) continue;
  let ts = null;
  if (typeof ad.startDate === 'number') ts = ad.startDate;
  else if (ad.startDate && /^\d+$/.test(String(ad.startDate))) ts = Number(ad.startDate);
  else if (ad.startDateFormatted) ts = Date.parse(ad.startDateFormatted);
  if (ts === null || !isFinite(ts)) continue;
  if (ts < 1e11) ts = ts * 1000;
  const daysRunning = Math.floor((now - ts) / DAY);
  if (daysRunning < 14) continue;
  const isTemplate = (s) => typeof s === 'string' && s.includes('{{');
  const bodyText = snap.body && typeof snap.body === 'object' ? snap.body.text : snap.body;
  const adCopy = (card && card.body) || (!isTemplate(bodyText) && bodyText) || snap.caption || '';
  results.push({
    ad_id: ad.adArchiveID || ad.adArchiveId || '',
    page_name: snap.pageName || ad.pageName || '',
    days_running: daysRunning,
    ad_copy: adCopy,
    video_url: videoUrl,
  });
}
results.sort((a, b) => b.days_running - a.days_running);
return results.slice(0, 3).map(r => ({ json: r }));

const ad = $('Loop Over Items').item.json;
let raw = $json.content?.parts?.[0]?.text ?? $json.text ?? $json.output ?? '';
let data = null;
if (raw && typeof raw === 'object') {
  data = raw;
} else {
  let s = String(raw).trim();
  s = s.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '');
  try { data = JSON.parse(s); } catch (e) { data = null; }
}
const fmt = (v) => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.map(fmt).join('\n');
  if (typeof v === 'object') return Object.entries(v).map(([k, val]) => k.replace(/_/g, ' ') + ': ' + fmt(val)).join('\n');
  return String(v);
};
const esc = (t) => String(t === null || t === undefined ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const b = (t) => '<b>' + esc(t) + '</b>';
const lines = [
  b('Competitor Name:') + ' ' + esc(ad.page_name),
  b('Days Running:') + ' ' + esc(ad.days_running),
  '<a href="' + String(ad.video_url).replace(/&/g, '&amp;').replace(/"/g, '&quot;') + '">▶️ Watch Winning Ad MP4</a>',
  ''
];
if (data) {
  const scriptsKey = Object.keys(data).find((k) => /(clone|script)/i.test(k) && !/description/i.test(k)) || Object.keys(data).find((k) => Array.isArray(data[k]));
  lines.push(b('3s Hook:') + ' ' + esc(fmt(data.spoken_hook_first_3s)));
  if (data.visual_hook_description) lines.push(b('Visual Hook:') + ' ' + esc(fmt(data.visual_hook_description)));
  lines.push('', b('Psychological Angle:') + ' ' + esc(fmt(data.psychological_angle)), '', b('Cloned Scripts:'));
  let scripts = scriptsKey ? data[scriptsKey] : [];
  if (!Array.isArray(scripts)) scripts = scripts && typeof scripts === 'object' ? Object.values(scripts) : [scripts];
  scripts.forEach((sc, i) => { lines.push('', b('Script ' + (i + 1) + ':'), esc(fmt(sc))); });
} else {
  lines.push(b('Gemini analysis (could not parse as JSON):'), esc(String(raw)));
}
let message = lines.join('\n');

if (message.length > 4000) {
  message = message.slice(0, 3990).replace(/<[^>]*$/, '').replace(/&[^;\s]*$/, '') + '...';
}
return { json: { message } };
